<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Sun Son Solar | Customer Dashboard</title>
    <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="<?= base_url('css/customer_dashboard.css') ?>">
    <link rel="stylesheet" href="<?= base_url('css/dashboard-workflows.css') ?>">
</head>
<body data-role="customer"><div class="layout">
    <aside class="sidebar"><a class="brand" href="<?= site_url() ?>"><img src="<?= base_url('images/Sun Son Solar.png') ?>" alt="Sun Son Solar logo" class="brand-logo"><span class="brand-name">Sun Son Solar</span></a><small>Customer Dashboard</small>
        <nav class="nav" aria-label="Customer navigation"><a href="<?= site_url() ?>">Homepage</a><a href="#overview">Overview</a><a href="#services">Scheduled Services</a><a href="#notifications">Notifications</a><a href="#history">History &amp; Receipts</a><a href="#profile">Profile &amp; Preferences</a><a href="#support">Support / Help</a></nav>
    </aside>
    <main class="main">
        <header class="top" id="overview"><div><h1>Customer Dashboard</h1><p>Hello, <?= esc($customer['first_name']) ?>. Manage your solar service requests and account.</p></div><span class="pill">Customer</span></header>
        <?php if (! empty($notice)): ?><p class="notice" role="status"><?= esc($notice) ?></p><?php endif; ?>
        <?php if (! empty($errors)): ?><div class="status" role="alert"><ul><?php foreach ($errors as $error): ?><li><?= esc($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
        <?php $pending = count(array_filter($requests, static fn ($row) => $row['status'] === 'Pending')); $completed = count(array_filter($requests, static fn ($row) => $row['status'] === 'Completed')); ?>
        <div class="stats" aria-label="Service summary"><div class="stat"><strong><?= count($requests) ?></strong><span>Total requests</span></div><div class="stat"><strong><?= $pending ?></strong><span>Pending</span></div><div class="stat"><strong><?= $completed ?></strong><span>Completed</span></div><div class="stat"><strong><?= count($notifications) ?></strong><span>Notifications</span></div></div>

        <section class="panel" id="services"><h2>Scheduled Services — View &amp; Manage</h2><p class="muted">You can see the current status and schedule. Contact support to request a change; only the team can confirm a schedule.</p><p><a class="btn" href="<?= site_url('requests?service=Quote') ?>">Request a Service</a></p>
            <div class="table-wrap"><table><thead><tr><th>Request</th><th>Service</th><th>Address</th><th>Preferred date</th><th>Submitted</th><th>Status</th><th>Manage</th></tr></thead><tbody><?php foreach ($requests as $request): ?><tr><td>#<?= esc($request['request_id']) ?></td><td><?= esc($request['service_type']) ?></td><td><?= esc($request['address']) ?></td><td><?= esc($request['preferred_date'] ?: 'Not scheduled') ?></td><td><?= esc($request['created_at']) ?></td><td><span class="tag"><?= esc($request['status']) ?></span></td><td><?php if ($request['status'] === 'Pending'): ?><form action="<?= site_url('customer/requests/cancel') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= esc($request['request_id']) ?>"><button class="btn danger" type="submit">Cancel request</button></form><?php elseif ($request['status'] === 'Confirmed'): ?><a href="#support">Ask about a change</a><?php endif; ?></td></tr><?php endforeach; ?><?php if ($requests === []): ?><tr><td colspan="7"><div class="empty-state">Your signed-in service requests will appear here.</div></td></tr><?php endif; ?></tbody></table></div>
        </section>

        <section class="panel" id="notifications"><h2>Notifications</h2><p class="muted">Reminders, schedule changes, and offers are in-app notices. Email and SMS are not sent.</p><?php foreach ($notifications as $notification): ?><div class="notice-row notice"><div><strong><?= esc($notification['title']) ?></strong><p><?= esc($notification['message']) ?></p><small><?= esc($notification['created_at']) ?> · <?= esc($notification['notification_type']) ?></small></div><?php if (! $notification['read_at']): ?><form action="<?= site_url('customer/notifications/read') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="notification_id" value="<?= esc($notification['notification_id']) ?>"><button class="btn secondary" type="submit">Mark read</button></form><?php else: ?><span>Read</span><?php endif; ?></div><?php endforeach; ?><?php if ($notifications === []): ?><div class="empty-state">No notifications yet.</div><?php endif; ?></section>

        <section class="panel" id="history"><h2>Service History, Payments &amp; Receipts</h2><p class="muted">Amounts below are payment records entered by the Sun Son Solar team after receiving payment. This site does not process payments.</p>
            <h3>Completed services</h3><div class="table-wrap"><table><thead><tr><th>Request</th><th>Service</th><th>Address</th><th>Request submitted</th><th>Status</th></tr></thead><tbody><?php foreach ($requests as $request): if ($request['status'] === 'Completed'): ?><tr><td>#<?= esc($request['request_id']) ?></td><td><?= esc($request['service_type']) ?></td><td><?= esc($request['address']) ?></td><td><?= esc($request['created_at']) ?></td><td><?= esc($request['status']) ?></td></tr><?php endif; endforeach; ?><?php if ($completed === 0): ?><tr><td colspan="5">No completed services recorded yet.</td></tr><?php endif; ?></tbody></table></div>
            <div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Request</th><th>Service</th><th>Amount</th><th>Method</th><th>Paid at</th></tr></thead><tbody><?php foreach ($payments as $payment): ?><tr><td><?= esc($payment['receipt_number']) ?></td><td>#<?= esc($payment['request_id']) ?></td><td><?= esc($payment['service_type']) ?></td><td>PHP <?= esc(number_format((float) $payment['amount'], 2)) ?></td><td><?= esc($payment['method']) ?></td><td><?= esc($payment['paid_at']) ?></td></tr><?php endforeach; ?><?php if ($payments === []): ?><tr><td colspan="6">No payment receipts have been recorded.</td></tr><?php endif; ?></tbody></table></div>
            <h3>Service usage</h3><?php foreach (['Consultation', 'Installation', 'Maintenance', 'Quote'] as $service): $used = count(array_filter($requests, static fn ($row) => $row['service_type'] === $service)); ?><div class="notice-row"><span><?= esc($service) ?></span><strong><?= $used ?> request<?= $used === 1 ? '' : 's' ?></strong></div><?php endforeach; ?>
        </section>

        <section class="panel" id="profile"><h2>Profile &amp; Preferences</h2><form action="<?= site_url('customer/profile') ?>" method="post" class="workflow-form"><?= csrf_field() ?><label>First name <input name="first_name" value="<?= esc($customer['first_name']) ?>" maxlength="50" required></label><label>Middle name <input name="middle_name" value="<?= esc($customer['middle_name'] ?? '') ?>" maxlength="50"></label><label>Last name <input name="last_name" value="<?= esc($customer['last_name']) ?>" maxlength="50" required></label><label>Email <input type="email" name="email" value="<?= esc($customer['email']) ?>" maxlength="100" required></label><label>Phone <input name="phone_number" value="<?= esc($customer['phone_number'] ?? '') ?>" pattern="09[0-9]{9}" required></label><label>Address <textarea name="address" maxlength="1000" required><?= esc($customer['address'] ?? '') ?></textarea></label><button class="btn" type="submit">Save profile</button></form>
            <h3>Change password</h3><form action="<?= site_url('customer/password') ?>" method="post" class="workflow-form"><?= csrf_field() ?><label>Current password <input type="password" name="current_password" autocomplete="current-password" required></label><label>New password <input type="password" name="new_password" minlength="8" maxlength="72" autocomplete="new-password" required></label><label>Confirm new password <input type="password" name="confirm_password" minlength="8" maxlength="72" autocomplete="new-password" required></label><button class="btn secondary" type="submit">Change password</button></form>
            <h3>Notification and contact preferences</h3><form action="<?= site_url('customer/preferences') ?>" method="post" class="workflow-form"><?= csrf_field() ?><label>Service reminders <select name="reminders_enabled"><option value="1" <?= (int) $preferences['reminders_enabled'] ? 'selected' : '' ?>>On</option><option value="0" <?= ! (int) $preferences['reminders_enabled'] ? 'selected' : '' ?>>Off</option></select></label><label>Offers <select name="offers_enabled"><option value="1" <?= (int) $preferences['offers_enabled'] ? 'selected' : '' ?>>On</option><option value="0" <?= ! (int) $preferences['offers_enabled'] ? 'selected' : '' ?>>Off</option></select></label><label>Preferred contact <select name="preferred_contact"><option value="email" <?= $preferences['preferred_contact'] === 'email' ? 'selected' : '' ?>>Email</option><option value="phone" <?= $preferences['preferred_contact'] === 'phone' ? 'selected' : '' ?>>Phone</option></select></label><button class="btn secondary" type="submit">Save preferences</button></form></section>

        <section class="panel" id="support"><h2>Support / Help</h2><p>Send a ticket to the team and follow replies here.</p><form action="<?= site_url('customer/tickets') ?>" method="post" class="workflow-form"><?= csrf_field() ?><label>Subject <input name="subject" maxlength="150" required></label><label>Message <textarea name="message" maxlength="3000" required></textarea></label><button class="btn" type="submit">Create support ticket</button></form>
            <?php foreach ($tickets as $ticket): ?><article class="ticket"><h3>Ticket #<?= esc($ticket['ticket_id']) ?> — <?= esc($ticket['subject']) ?> <span class="tag"><?= esc($ticket['status']) ?></span></h3><?php foreach (($ticketMessages[$ticket['ticket_id']] ?? []) as $message): ?><div class="notice"><strong><?= esc(ucfirst($message['sender_type'])) ?></strong> · <?= esc($message['sent_at']) ?><p><?= nl2br(esc($message['message'])) ?></p></div><?php endforeach; ?><?php if ($ticket['status'] !== 'Closed'): ?><form action="<?= site_url('customer/tickets/reply') ?>" method="post" class="workflow-form"><?= csrf_field() ?><input type="hidden" name="ticket_id" value="<?= esc($ticket['ticket_id']) ?>"><label>Reply <textarea name="message" maxlength="3000" required></textarea></label><button class="btn secondary" type="submit">Send reply</button></form><?php endif; ?></article><?php endforeach; ?><?php if ($tickets === []): ?><div class="empty-state">No support tickets yet.</div><?php endif; ?></section>

        <footer class="footer-section"><h3>Sun Son Solar</h3><p>Customer services · <?= date('Y') ?></p><p><a href="<?= site_url() ?>#contact">Contact the team</a> · <a href="<?= site_url() ?>">Homepage</a></p><form action="<?= site_url('logout') ?>" method="post"><?= csrf_field() ?><button class="btn secondary" type="submit">Sign out</button></form></footer>
    </main>
</div></body></html>
